`timescale 1ns/1ps
module oracle_tb; reg clk=0,rst=1,wr_en=0,rd_en=0; reg [15:0] din=0; wire [15:0] dout; wire full,empty; wire [3:0] count; integer i; sync_fifo8x16 dut(.clk(clk),.rst(rst),.wr_en(wr_en),.rd_en(rd_en),.din(din),.dout(dout),.full(full),.empty(empty),.count(count)); always #5 clk=~clk;
task push; input [15:0] v; begin din=v;wr_en=1;rd_en=0;@(posedge clk);#1;wr_en=0;end endtask task pop; input [15:0] v; begin rd_en=1;wr_en=0;@(posedge clk);#1;rd_en=0;if(dout!==v)begin $display("FAIL: fifo data");$finish;end end endtask
initial begin repeat(2)@(posedge clk);#1;rst=0;if(!empty||count!=0)begin $display("FAIL: reset");$finish;end for(i=0;i<8;i=i+1)push(16'h1000+i);if(!full||count!=8)begin $display("FAIL: full");$finish;end for(i=0;i<4;i=i+1)pop(16'h1000+i);din=16'hbeef;wr_en=1;rd_en=1;@(posedge clk);#1;wr_en=0;rd_en=0;if(count!=4||dout!==16'h1004)begin $display("FAIL: simultaneous");$finish;end pop(16'h1005);pop(16'h1006);pop(16'h1007);pop(16'hbeef);if(!empty||count!=0)begin $display("FAIL: empty");$finish;end $display("PASS: blind fifo");$finish;end endmodule
